import { Assets, type Spritesheet, type Texture } from 'pixi.js';
import { ISLAND_FRAMES } from './arena.ts';

/** Runtime assets generated by scripts/prepare-assets.ts. */
const ASSET_URLS = {
  ships: '/game/ships.json',
  tiles: '/game/tiles.json',
  ui: '/game/ui.json',
  water: '/game/water@2x.png',
} as const;

/** First ship frame of each colour: blue player, red chasers, black shooters. */
const SHIP_COLORS = { player: 5, chaser: 3, shooter: 2 } as const;

export type ShipColor = keyof typeof SHIP_COLORS;

/**
 * Ship frame for a colour and damage stage (0 intact, 1 damaged, 2 badly damaged, 3 wreck).
 * In the ships atlas each stage is six frames after the previous one (e.g. 5, 11, 17, 23).
 */
export function shipFrame(color: ShipColor, stage: number): string {
  return `ship_${SHIP_COLORS[color] + 6 * stage}`;
}

type SheetName = 'ships' | 'tiles' | 'ui';

/** Frames the game renders. A missing frame fails the load instead of drawing an empty sprite. */
const REQUIRED_FRAMES: Record<SheetName, readonly string[]> = {
  ships: [
    ...(Object.keys(SHIP_COLORS) as ShipColor[]).flatMap((color) =>
      [0, 1, 2, 3].map((stage) => shipFrame(color, stage)),
    ),
    'cannon_ball',
    'explosion_1',
    'explosion_2',
    'explosion_3',
    'fire_1',
    'fire_2',
  ],
  tiles: Object.values(ISLAND_FRAMES),
  ui: ['enemy_health_frame', 'enemy_health_fill_green', 'enemy_health_fill_red'],
};

export type GameTextures = {
  ships: Spritesheet;
  tiles: Spritesheet;
  ui: Spritesheet;
  water: Texture;
};

/** Returns a frame of a loaded spritesheet, failing loudly when it does not exist. */
export function getFrame(sheet: Spritesheet, name: string): Texture {
  const texture = sheet.textures[name];
  if (!texture) throw new Error(`Missing spritesheet frame "${name}"`);
  return texture;
}

async function assertRequiredFrames(textures: GameTextures): Promise<void> {
  for (const sheetName of Object.keys(REQUIRED_FRAMES) as SheetName[]) {
    const missing = REQUIRED_FRAMES[sheetName].filter(
      (name) => !(name in textures[sheetName].textures),
    );
    if (missing.length > 0) {
      // Drop the invalid sheet from the asset cache so a retry fetches it again.
      await Assets.unload(ASSET_URLS[sheetName]);
      throw new Error(`Spritesheet "${sheetName}" is missing frames: ${missing.join(', ')}`);
    }
  }
}

let pending: Promise<GameTextures> | null = null;

let progress = 0;
const progressListeners = new Set<() => void>();

function setProgress(value: number): void {
  progress = value;
  progressListeners.forEach((listener) => listener());
}

export function subscribeAssetProgress(listener: () => void): () => void {
  progressListeners.add(listener);
  return () => progressListeners.delete(listener);
}

export function getAssetProgress(): number {
  return progress;
}

async function loadAll(): Promise<GameTextures> {
  setProgress(0);
  const loaded = await Assets.load(Object.values(ASSET_URLS), setProgress);
  const textures: GameTextures = {
    ships: loaded[ASSET_URLS.ships] as Spritesheet,
    tiles: loaded[ASSET_URLS.tiles] as Spritesheet,
    ui: loaded[ASSET_URLS.ui] as Spritesheet,
    water: loaded[ASSET_URLS.water] as Texture,
  };
  await assertRequiredFrames(textures);
  return textures;
}

/**
 * Loads the game textures once and shares them between matches. A failed load is not
 * cached, so calling this again performs a real retry (PixiJS also drops failed requests
 * from its own cache).
 */
export function loadGameAssets(): Promise<GameTextures> {
  pending ??= loadAll().catch((error: unknown) => {
    pending = null;
    throw error;
  });
  return pending;
}
